create table if not exists doctors (id bigserial primary key, code varchar(50) not null unique, name varchar(150) not null, hospital varchar(200), address varchar(500), phone varchar(30), active boolean not null default true);
create table if not exists investigations (id bigserial primary key, code varchar(50) not null unique, name varchar(200) not null, modality varchar(80) not null, amount numeric(12,2) not null default 0, active boolean not null default true);
create table if not exists patients (id bigserial primary key, patient_code varchar(50) unique, name varchar(150) not null, father_husband_name varchar(150), age integer, gender varchar(30), phone varchar(30), email varchar(150), address varchar(500), created_at timestamp not null default current_timestamp);
create table if not exists referral_parties (id bigserial primary key, code varchar(50) not null unique, name varchar(150) not null, type varchar(20) not null check(type in ('DOCTOR','STAFF')), hospital varchar(200), phone varchar(30), active boolean not null default true);
create table if not exists visits (id bigserial primary key, patient_id bigint not null references patients(id), visit_date date not null, referral_party_id bigint references referral_parties(id), gross_amount numeric(12,2) not null default 0, discount_amount numeric(12,2) not null default 0, final_amount numeric(12,2) not null default 0, remarks varchar(1000));
create table if not exists visit_investigations (id bigserial primary key, visit_id bigint not null references visits(id) on delete cascade, investigation_id bigint not null references investigations(id), amount numeric(12,2) not null, concession boolean not null default false, discount_amount numeric(12,2) not null default 0, discount_reason varchar(500), referral_amount numeric(12,2) not null default 0);
create table if not exists payments (id bigserial primary key, visit_id bigint not null references visits(id) on delete cascade, mode varchar(20) not null check(mode in ('CASH','UPI','CARD')), amount numeric(12,2) not null, paid_at timestamp not null default current_timestamp, reference_no varchar(100));
create index if not exists idx_patients_phone on patients(phone); create index if not exists idx_visits_date on visits(visit_date); create index if not exists idx_visits_referral on visits(referral_party_id);
